import sys
import numpy as np
def main():
    data=sys.stdin.buffer.read().split()
    p=0
    N=int(data[p]); M=int(data[p+1]); Q=int(data[p+2]); p+=3
    edges=[]
    for _ in range(M):
        a=int(data[p])-1; b=int(data[p+1])-1; c=int(data[p+2]); p+=3
        edges.append((a,b,c))
    queries=[]
    closed=set()
    for _ in range(Q):
        t=data[p]
        if t==b'1':
            i=int(data[p+1])-1; p+=2
            closed.add(i); queries.append((1,i,0))
        else:
            x=int(data[p+1])-1; y=int(data[p+2])-1; p+=3
            queries.append((2,x,y))
    INF=10**18
    d=np.full((N,N),INF,dtype=np.int64)
    np.fill_diagonal(d,0)
    for i,(a,b,c) in enumerate(edges):
        if i not in closed:
            if c<d[a,b]:
                d[a,b]=c; d[b,a]=c
    for k in range(N):
        d=np.minimum(d,d[:,k:k+1]+d[k:k+1,:])
    ans=[]
    for t,u,v in reversed(queries):
        if t==2:
            ans.append(int(d[u,v]))
        else:
            a,b,c=edges[u]
            d=np.minimum(d,np.minimum(d[:,a:a+1]+c+d[b:b+1,:], d[:,b:b+1]+c+d[a:a+1,:]))
    out=[]
    for x in reversed(ans):
        out.append(str(x if x<INF else -1))
    sys.stdout.write("\n".join(out)+("\n" if out else ""))
