import sys
from math import factorial
def main():
    A,B,M = map(int, sys.stdin.read().split())
    N = A*B-1
    lam = [A]*B; lam[-1] -= 1
    conj = [sum(1 for r in lam if r > j) for j in range(A)]
    h = 1
    for i, r in enumerate(lam):
        for j in range(r):
            h *= (r-j-1) + (conj[j]-i-1) + 1
    f = factorial(N)//h
    LIMIT = 3000000
    if f > LIMIT:
        print(0); return
    T = [[0]*l for l in lam]
    fill = [0]*B
    cnt = 0
    def evac(T):
        T2 = [row[:] for row in T]
        out = [[0]*len(r) for r in T]
        for lab in range(N, 0, -1):
            i = j = 0
            while True:
                cand = []
                if i+1 < len(T2) and j < len(T2[i+1]): cand.append((T2[i+1][j], i+1, j))
                if j+1 < len(T2[i]): cand.append((T2[i][j+1], i, j+1))
                if not cand: break
                v, ci, cj = min(cand)
                T2[i][j] = v; i, j = ci, cj
            out[i][j] = lab
            T2[i].pop(j)
            if not T2[i]: T2.pop(i)
        return out
    def rec(v):
        nonlocal cnt
        if v > N:
            E = evac(T)
            if T[0][A-1] + E[B-1][0] >= A*B+1:
                cnt += 1
            return
        for i in range(B):
            j = fill[i]
            if j < lam[i] and (i == 0 or fill[i-1] > j):
                T[i][j] = v; fill[i] += 1
                rec(v+1)
                fill[i] -= 1
    rec(1)
    print(f % M * cnt % M)
