def feas(H,U,D,X):
    n=len(U)
    a=b=None
    for i in range(n):
        lo=max(0,H-D[i]); hi=min(U[i],H)
        if lo>hi: return False
        if i==0: a,b=lo,hi
        else:
            a,b=max(lo,a-X),min(hi,b+X)
            if a>b: return False
    return True
def solve(n,X,U,D):
    lo,hi=0,min(u+d for u,d in zip(U,D))
    while lo<hi:
        m=(lo+hi+1)//2
        if feas(m,U,D,X): lo=m
        else: hi=m-1
    return sum(U)+sum(D)-n*lo
def brute(n,X,U,D):
    best=None
    for H in range(0,max(u+d for u,d in zip(U,D))+1):
        # enumerate U' choices
        opts=[[u for u in range(0,min(U[i],H)+1) if 0<=H-u<=D[i]] for i in range(n)]
        for c in itertools.product(*opts):
            if all(abs(c[i]-c[i+1])<=X for i in range(n-1)):
                cost=sum(U)+sum(D)-n*H
                if best is None or cost<best: best=cost
    return best
