class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1]*(n+2)
        for i in range(1, n+2):
            fact[i] = fact[i-1]*i
        def ways(o, e, q):
            L = o+e
            if L == 0:
                return 1
            if q == 1:
                if o != (L+1)//2 or e != L//2:
                    return 0
            else:
                if e != (L+1)//2 or o != L//2:
                    return 0
            return fact[o]*fact[e]
        O = (n+1)//2
        E = n//2
        used = [False]*(n+1)
        res = []
        prev = None
        for pos in range(n):
            chosen = False
            for x in range(1, n+1):
                if used[x]:
                    continue
                if prev is not None and (x % 2) == (prev % 2):
                    continue
                o2 = O - (x % 2)
                e2 = E - (1 - x % 2)
                q = 1 - x % 2
                c = ways(o2, e2, q)
                if k <= c:
                    used[x] = True
                    res.append(x)
                    O, E = o2, e2
                    prev = x
                    chosen = True
                    break
                k -= c
            if not chosen:
                return []
        return res

