class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        full = (1 << k) - 1
        def rot(m, s):
            return ((m << s) | (m >> (k - s))) & full
        pw = [pow(10, i, k) for i in range(n)]
        coef = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                coef.append(pw[i] % k)
            else:
                coef.append((pw[i] + pw[j]) % k)
        suf = [0] * (h + 1)
        suf[h] = 1
        for i in range(h - 1, -1, -1):
            c = coef[i]
            lo = 1 if i == 0 else 0
            m = 0
            for d in range(lo, 10):
                m |= rot(suf[i + 1], (d * c) % k)
            suf[i] = m
        if not (suf[0] & 1):
            return ""
        need = 0
        digs = []
        for i in range(h):
            c = coef[i]
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                r = (need - d * c) % k
                if (suf[i + 1] >> r) & 1:
                    digs.append(d)
                    need = r
                    break
        s = ''.join(map(str, digs))
        return s + s[:n // 2][::-1]

