def solve(N,M,L,A,B,C):
    vals=A+B+C
    n=N+M+L
    full=(1<<n)-1
    # cards indices: 0..N-1 A, N..N+M-1 B, rest C
    memo={}
    def win(T,Am,turn):
        key=(T,Am,turn)
        r=memo.get(key)
        if r is not None: return r
        table=full^T^Am
