                tb=table|lb
                # no take
                if not win(T2,A2,1-turn):
                    res=True;break
                t=tb&~lb
                # possible takes: table cards smaller than c
                while t and not res:
                    tl=t&-t; t^=tl
                    j=tl.bit_length()-1
                    if vals[j]<c:
                        if turn==0:
                            nt,na=T2|tl,A2
                        else:
                            nt,na=T2,A2|tl
                        if not win(nt,na,1-turn):
                            res=True
        memo[key]=res
        return res
    # initial: T hand = A mask
    Tm=(1<<N)-1
    Am=((1<<M)-1)<<N
    return "Takahashi" if win(Tm,Am,0) else "Aoki"

