from bisect import bisect_left

def occ(t, x):
    n = len(t)
    if not x:
        return list(range(n + 1))
    m = len(x)
    pi = [0] * m
    k = 0
    for q in range(1, m):
        while k and x[q] != x[k]:
            k = pi[k - 1]
        if x[q] == x[k]:
            k += 1
        pi[q] = k
    res = []
    k = 0
    for i, ch in enumerate(t):
        while k and ch != x[k]:
            k = pi[k - 1]
        if ch == x[k]:
            k += 1
        if k == m:
            res.append(i - m + 1)
            k = pi[k - 1]
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a = p.index('*')
        b = p.index('*', a + 1)
        A, B, C = p[:a], p[a+1:b], p[b+1:]
        oA = occ(s, A)
        oB = occ(s, B)
        oC = occ(s, C)
        lA, lB, lC = len(A), len(B), len(C)
        ans = -1
        for i in oA:
            idx = bisect_left(oB, i + lA)
            if idx == len(oB):
                break
            k = oB[idx]
            idx2 = bisect_left(oC, k + lB)
            if idx2 == len(oC):
                continue
            m = oC[idx2]
            L = m + lC - i
            if ans == -1 or L < ans:
                ans = L
        return ans

