import numpy as np
def solve(N,W,items):
    groups = {}
    for w,v in items: groups.setdefault(w, []).append(v)
    dp = np.zeros(W + 1, dtype=np.int64)
    for w, vs in groups.items():
        K = W // w
        heap = []
        for idx, v in enumerate(vs):
            if v - 1 > 0: heap.append((-(v - 1), idx, 1))
        heapq.heapify(heap)
        vals = []
        while heap and len(vals) < K:
            negval, idx, k = heapq.heappop(heap)
            vals.append(-negval)
            nv = vs[idx] - (2 * (k + 1) - 1)
            if nv > 0: heapq.heappush(heap, (-nv, idx, k + 1))
        for val in vals:
            dp[w:] = np.maximum(dp[w:], dp[:-w] + val)
    return int(dp[W])
