import sys
def solve(K,S,T):
    n,m=len(S),len(T)
    if abs(n-m)>K: return "No"
    MOD=(1<<61)-1; B=1000003
    def pref(s):
        H=[0]*(len(s)+1); h=0
        for idx,c in enumerate(s):
            h=(h*B+ord(c))%MOD; H[idx+1]=h
        return H
    HS=pref(S); HT=pref(T)
    P=[1]*(max(n,m)+2)
    for i in range(1,len(P)): P[i]=P[i-1]*B%MOD
    def lce(i,j):
        mx=min(n-i,m-j); lo=0; hi=mx
        while lo<hi:
            mid=(lo+hi+1)//2
            if (HS[i+mid]-HS[i]*P[mid])%MOD==(HT[j+mid]-HT[j]*P[mid])%MOD: lo=mid
            else: hi=mid-1
        return lo
    prev={}
    for d in range(K+1):
        cur={}
        for k in range(-d,d+1):
            if d==0:
                best=0
            else:
                best=-1
                if k in prev: best=max(best,prev[k]+1)
                if k-1 in prev: best=max(best,prev[k-1])
                if k+1 in prev: best=max(best,prev[k+1]+1)
            if best<0: continue
            i=best; j=i+k
            if i>n or j>m or j<0: continue
            i+=lce(i,j)
            cur[k]=i
        if (m-n) in cur and cur[m-n]>=n: return "Yes"
        prev=cur
    return "No"
