        INF = float('inf')
        mn = [INF] * k
        ans = -INF
        p = 0
        for j in range(n + 1):
            if j > 0:
                p += nums[j - 1]
            r = j % k
            if mn[r] != INF:
                v = p - mn[r]
                if v > ans:
                    ans = v
            if p < mn[r]:
                mn[r] = p
        return int(ans)

