def fast(R):
    T = 4*R*R
    total = 0
    b = None
    a = 0
    b = 0
    # find initial b for a=0
    while (2*a+1)**2 + (2*(b+1)+1)**2 <= T:
        b += 1
    bmax = b
    while True:
        A = (2*a+1)**2
        if A + 1 > T:
            break
        while bmax >= 0 and A + (2*bmax+1)**2 > T:
            bmax -= 1
        if bmax < 0:
            break
        w = 1 if a == 0 else 2
        total += w * (1 + 2*bmax)
        a += 1
    return total

def brute(R):
    c = 0
    for i in range(-R-2, R+3):
        for j in range(-R-2, R+3):
            ok = True
            for di in (0.5,-0.5):
                for dj in (0.5,-0.5):
                    if (i+di)**2+(j+dj)**2 > R*R: ok=False
            c += ok
    return c

for R in range(1,25):
    assert fast(R)==brute(R),R
