class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        masks = [1] * n  # bit s set => total decrement s achievable at index i
        if all(x == 0 for x in nums):
            return 0
        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                masks[i] |= masks[i] << v
            if all((masks[i] >> nums[i]) & 1 for i in range(n)):
                return k + 1
        return -1

