    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True]*N
        sieve[0] = sieve[1] = False
        for i in range(2, int(N**0.5)+1):
            if sieve[i]:
                for j in range(i*i, N, i):
                    sieve[j] = False
        def isp(x):
            return x >= 2 and sieve[x]
        if isp(n) or isp(m):
            return -1
        if n == m:
            return n
        L = len(str(n))
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist.get(u, INF):
                continue
            if u == m:
                return d
            p = 1
            for i in range(L):
                dig = (u // p) % 10
                for nd in (dig + 1, dig - 1):
                    if 0 <= nd <= 9:
                        v = u + (nd - dig) * p
                        if isp(v):
                            continue
                        nd2 = d + v
                        if nd2 < dist.get(v, INF):
                            dist[v] = nd2
                            heapq.heappush(pq, (nd2, v))
                p *= 10
        return -1

