import numpy as np

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        a = np.array(nums, dtype=np.int64)
        ar = np.arange(n + 1, dtype=np.int64)
        prev = np.zeros(n + 1, dtype=np.int64)
        total = 0
        for i in range(n - 1, 0, -1):
            cur = np.zeros(n + 1, dtype=np.int64)
            if i + 1 < n:
                eq = (a[i+1:n] == a[i]).astype(np.int64)
                cur[i+1:n] = eq * (prev[i+2:n+1] + 1)
            if i + 1 < n:
                total += int(np.count_nonzero(cur[i+1:n] >= ar[i+1:n] - i))
            if 2 * i <= n - 1 and nums[0:i] == nums[i:2 * i]:
                total += n - 2 * i
                if 2 * i < n:
                    total -= int(np.count_nonzero(cur[2*i:n] >= ar[2*i:n] - i))
            prev = cur
        return total

