class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        S = set(map(tuple, points))
        pts = list(S)
        best = -1
        for (x1, y1) in pts:
            for (x2, y2) in pts:
                if x1 < x2 and y1 < y2:
                    if (x1, y2) not in S or (x2, y1) not in S:
                        continue
                    ok = True
                    for (x, y) in pts:
                        if x1 <= x <= x2 and y1 <= y <= y2:
                            if (x, y) not in ((x1, y1), (x1, y2), (x2, y1), (x2, y2)):
                                ok = False
                                break
                    if ok:
                        best = max(best, (x2 - x1) * (y2 - y1))
        return best

